export async function execute(args = {}) {
  const out = {}
  for (const o of args.objects || []) Object.assign(out, o)
  return { value: out }
}

import test from 'node:test'
import assert from 'node:assert'
import { execute } from '../lib/impl.js'
test('merge', async () => {
  const r = await execute({ objects: [{ a: 1 }, { b: 2 }, { a: 3 }] })
  assert.deepEqual(r.value, { a: 3, b: 2 })
})
